on_rendering_sub = None
frameCounter = 0
waitFrames = 10
nucleus_success = False

class StageLoader:
    def __init__(self, usd_context) -> None:
        self._usd_context = usd_context
        self._current_url = ""
        ed = carb.eventdispatcher.get_eventdispatcher()
        self._stage_event_sub = [
            ed.observe_event(
                event_name=usd_context.stage_event_name(event),
                on_event=func
            )
            for event, func in (
                (omni.usd.StageEventType.OPENING, self.on_opening),
                (omni.usd.StageEventType.ASSETS_LOADED, lambda _: self.on_assets_loaded()),
                (omni.usd.StageEventType.OPEN_FAILED, lambda _: self.on_open_failed())
            )
        ]
        self._loading = False
        self._time_out = False
        self._future_assets_loaded = asyncio.Future()
        self._start_ts = 0
        
    def loading(self):
        return self._loading

    async def wait(self, timeout: float = 60.0):
        try:
            print(f"Loading assets will timeout in {timeout:.2f}s")
            await asyncio.wait_for(self._future_assets_loaded, timeout=timeout)
            return self._result()
        except asyncio.TimeoutError:
            print("Loading assets timed out.")
            self._loading = False
            self._time_out = True
            self._reset_future(False)
            return self._result()

    def _reset_future(self, result: bool) -> None:
        """Helper method to safely reset the future"""
        if not self._future_assets_loaded.done():
            try:
                self._future_assets_loaded.set_result(result)
            except asyncio.InvalidStateError:
                print("_reset_future: asyncio.InvalidStateError")
                return

    def _result(self):
        future = self._future_assets_loaded
        if not future.done() or future.cancelled():
            return False, self._time_out

        try:
            return self._future_assets_loaded.result(), self._time_out
        except asyncio.CancelledError:
            # Treat cancellation as failure, but keep timeout flag
            print("_result: asyncio.CancelledError")
            return False, self._time_out

    async def load(self, url: str, timeout: float = 60.0):
        if self._loading:
            carb.log_error("*** Cannot load a new stage while one is loading")
            return

        # enable the flag, track the current url being loaded
        self._loading = True
        self._current_url = url

        try:
            result = await asyncio.wait_for(
                self._usd_context.open_stage_async(url),
                timeout=timeout
            )
            return result

        except asyncio.TimeoutError:
            self._loading = False
            self._time_out = True
            return False, "Timeout"

        except Exception as e:
            self._loading = False
            print(f"Exeception when calling _usd_context.open_stage_async: {e}")
            return False, str(e)

    def close_stage(self):
        self._usd_context.close_stage()

    def on_opening(self, e):
        url = e["val"]
        if self._loading and url and url in self._current_url:
            self._start_ts = time.monotonic()

    def on_assets_loaded(self):
        if self._loading:
            self._loading = False
            if not self._future_assets_loaded.done():
                self._future_assets_loaded.set_result(True)

    def on_open_failed(self):
        if self._loading:
            self._loading = False
            print(f"{self._current_url} failed to load.")
            if not self._future_assets_loaded.done():
                self._future_assets_loaded.set_result(False)


def on_rendering_event(e: carb.eventdispatcher.Event):
    global frameCounter
    frame_number = e["frame_number"]
    if frame_number is not None:
        frameCounter += 1


def on_connect_success(name, url, server_type):
    global nucleus_success
    nucleus_success = True
    return


def on_connect_failure(name, url):
    return


def is_running_in_gitlab():
    return bool(os.getenv("GITLAB_CI"))


def clear_directory_contents(directory_path):
    """
    Clears contents of a directory.

    Args:
        directory_path (str): Path to the directory to clear
    """
    try:
        if not os.path.exists(directory_path) or not os.path.isdir(directory_path):
            return

        # Use os.scandir() for better performance
        with os.scandir(directory_path) as entries:
            for entry in entries:
                # print(f"Removing {entry.path}")
                try:
                    if entry.is_dir():
                        shutil.rmtree(entry.path)
                        # print(f"Successfully removed {entry.path}")
                    else:
                        os.remove(entry.path)
                        # print(f"Successfully removed {entry.path}")
                except (PermissionError, OSError) as e:
                    carb.log_warn(f"Error removing {entry.path}: {e}")

    except Exception as e:
        carb.log_warn(f"Failed to clear directory: {e}")


def free_ov_cache():
    """
    Remove the contents of cache directories.
    """
    try:
        # List of paths to clear - initialize this first
        paths_to_clear = []

        # Get the cache path using tokens
        settings = carb.settings.get_settings()
        texture_cache_path = settings.get(
            "/rtx-transient/resourcemanager/localTextureCachePath"
        )

        # Add texture cache path if it exists and is not empty
        if texture_cache_path and texture_cache_path.strip():
            paths_to_clear.append(("texture_cache", texture_cache_path.strip()))

        tokens = carb.tokens.get_tokens_interface()
        global_cache_path = tokens.resolve("${omni_global_cache}")
        print(f"global_cache_path: {global_cache_path}")
        global_texture_cache_path = ""
        if global_cache_path and global_cache_path.strip():
            global_texture_cache_path = os.path.join(global_cache_path.strip(), "texturecache")
        print(f"global_texture_cache_path: {global_texture_cache_path}")

        # Add omni client cache path
        if global_texture_cache_path and global_texture_cache_path.strip():
            paths_to_clear.append(("global_texture_cache", global_texture_cache_path.strip()))

        # Clear each path safely
        for path_name, path_to_clear in paths_to_clear:
            try:
                if os.path.exists(path_to_clear):
                    if os.path.isdir(path_to_clear):
                        # Remove directory contents but keep the directory
                        clear_directory_contents(path_to_clear)
                    else:
                        # Remove single file
                        os.remove(path_to_clear)
            except Exception as e:
                carb.log_warn(f"Failed to clear {path_name} path {path_to_clear}: {e}")

    except Exception as e:
        carb.log_warn(f"Failed to get cache paths: {e}")
        return

    return


async def main(args):
    global on_rendering_sub
    global frameCounter
    global waitFrames
    global nucleus_success

    iteration_times = []  # Track all iteration times
    start_datetime = datetime.now()
    # Next time related vars. are in seconds
    avg_time = 0
    elapsed = 0
    start_time = time.monotonic()
    kit_start_time = 60 # Account for test.unit / kit initialization
    wrapping_out_time = 60 # Account for shutting down
    test_timeout = max(args.timeout - kit_start_time - wrapping_out_time, 0)

    # Free the ov cache to avoid runners from running out of disk space
    # if is_running_in_gitlab():
    free_ov_cache()

    usdContext = omni.usd.get_context()
    app = omni.kit.app.get_app()
    renderer = omni.kit.renderer_capture.acquire_renderer_capture_interface()

    on_rendering_sub = carb.eventdispatcher.get_eventdispatcher().observe_event(
        event_name=usdContext.stage_rendering_event_name(omni.usd.StageRenderingEventType.NEW_FRAME, True),
        on_event=on_rendering_event,
        observer_name="reloading_stress_test"
    )

    print("=" * 70)
    print(f"{args.name} Loading: {args.stage}")

    broken_url = omni.client.break_url(args.stage)
    server_url = omni.client.make_url(scheme='omniverse', host=broken_url.host)
    # Let's thrust infra. Commenting next block
    # Check if nucleus is reachable
    # broken_url = omni.client.break_url(args.stage)
    # server_url = omni.client.make_url(scheme='omniverse', host=broken_url.host)
    # print(f"Server URL: {server_url}")
    # nucleus_success = False
    # nc = NucleusConnector()
    # if broken_url.scheme == 'omniverse':
    #     await nc.connect_server_async(broken_url.host, server_url,
    #                                     on_success_fn=on_connect_success,
    #                                     on_failed_fn=on_connect_failure)
    # nc.destroy() # let's clean.
    # if not nucleus_success:
    #     print(f"[error] {args.name} Failed to connect to {broken_url.host} at {server_url}")
    #     app.post_uncancellable_quit(-1)
    #     return

    elapsed = time.monotonic() - start_time
    iteration_time = 0
    time_remaining = 0
    for i in range(args.iterations):
        print(f"{args.name} Iteration {i + 1} of {args.iterations}")

        iteration_start = time.monotonic()

        if i == 0:
            time_remaining = test_timeout - elapsed
            print(f"Test's timeout after initialization: {time_remaining:.2f}s")
        else:
            time_remaining = time_remaining - iteration_time
            if time_remaining < avg_time:
                print(f"{args.name} Timeout likely to be reached at stage opening for iteration {i}. Finalizing test before timeout occurs.")
                break
        print(f"time_remaining: {time_remaining:.2f}s")

        usd_loader = StageLoader(usdContext)
        load_start = time.monotonic()
        open_stage_success, reason = await usd_loader.load(args.stage, timeout=time_remaining)
        load_end = time.monotonic()
        load_time = load_end - load_start

        if open_stage_success is True:
            print("Stage opened.")
            time_remaining = time_remaining - load_time
            print(f"time_remaining after opening: {time_remaining:.2f}s")
            if i > 0 and time_remaining < avg_time:
                print(f"{args.name} Timeout likely to be reached at asset loading for iteration {i}. Finalizing test before timeout occurs.")
                can_close_stage = usdContext.can_close_stage()
                print(f"can_close_stage: {can_close_stage}")
                if can_close_stage:
                    usd_loader.close_stage()
                break

            # Wait for assets to load for rendering
            result, time_out_assets = await usd_loader.wait(timeout=time_remaining)
            print(f"Assets loaded: {result}, time_out_assets: {time_out_assets}")
            if time_out_assets:
                print(f"[warning] {args.name} Stage loading timeout after {time_remaining:.2f}s. Finalizing test.")
                can_close_stage = usdContext.can_close_stage()
                print(f"can_close_stage: {can_close_stage}")
                if can_close_stage:
                    usd_loader.close_stage()
                omni.client.sign_out(server_url)
                end_datetime = datetime.now()
                print(f"{args.name} Test script started at {start_datetime:%H:%M:%S}. Ended at {end_datetime:%H:%M:%S}")
                await app.next_update_async()
                app.post_uncancellable_quit(0)
                return
        else:
            omni.client.sign_out(server_url)
            print(f"open_stage_success: {open_stage_success}, reason: {reason}")
            print(f"[error] {args.name} Stage not opened. Finalizing test.")
            await app.next_update_async()
            app.post_uncancellable_quit(0)
            return

        # Allow to render n-waitFrames
        usdContext.reset_renderer_accumulation()
        frameCounter = 0
        while frameCounter < waitFrames:
            await app.next_update_async()

        # Capture frame if requested during first iteration
        if args.output is not None and i == 0:
            if args.ujitso:
                await wait_for_streaming()
            renderer.capture_next_frame_swapchain(str(args.output))
            await app.next_update_async()
            renderer.wait_async_capture()

        usd_loader.close_stage()

        iteration_end = time.monotonic()
        iteration_time = iteration_end - iteration_start
        iteration_times.append(iteration_time)
        elapsed = time.monotonic() - start_time
        avg_time = elapsed / (i + 1)

        print(f"{args.name} Iteration {i + 1} took {iteration_time:.2f}s (avg: {avg_time:.2f}s elapsed: {elapsed:.2f}s)")

        # Exit if the estimated time (elapsed + avg_time)
        # to complete the iteration i+1 is greater than the test timeout
        if test_timeout > 0 and i+1 <= args.iterations:
            if elapsed + avg_time >= test_timeout:
                print(f"{args.name} Timeout likely to be reached for iteration {i+2}. Finalizing test before timeout occurs.")
                break

    # Print final statistics
    if iteration_times:
        print(f"{args.name} Total iterations: {len(iteration_times)}. Avg time per iteration: {avg_time:.2f}s. Total time: {elapsed:.2f}s")

    end_datetime = datetime.now()
    print(f"{args.name} Test script started at {start_datetime:%H:%M:%S}. Ended at {end_datetime:%H:%M:%S}")

    omni.client.sign_out(server_url)
    await app.next_update_async()
    app.post_uncancellable_quit(0)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()

    parser.add_argument("--name", help="Name of the test", type=str, default="", required=False)
    parser.add_argument("--iterations", help="Number of iterations.", type=int, default=100, required=True)
    parser.add_argument("--timeout", help="Maximum time in seconds to run iterations", type=int, default=0, required=False)
    parser.add_argument("--stage", help="Full path to USD stage to render", required=False)
    parser.add_argument("--output", help="Prefix path to captured golden including path", required=False)
    parser.add_argument("--ujitso", help="Flag that indicates UJITSO is enabled or disabled", type=bool, default=False, required=False)
    args, unknown = parser.parse_known_args()

    print(f"args: {args.timeout}")

    asyncio.ensure_future(main(args))
